import React, { lazy, Suspense } from 'react';
import { Helmet } from 'react-helmet';
import { ChakraProvider } from '@salesforce/retail-react-app/app/components/shared/ui';
import { ZimmTokensGlobal } from '../../theme/zimmTokensGlobal';
import { ZimmFontFace } from '../../theme/fontFace';
import { UiCopyProvider } from '../uiCopyProvider';

// Removes focus for non-keyboard interactions for the whole application
import 'focus-visible/dist/focus-visible';

import theme from '../../theme';
import { MultiSiteProvider, StoreLocatorProvider } from '@salesforce/retail-react-app/app/contexts';
import {
  resolveSiteFromUrl,
  getParamsFromPath,
  getSites,
  getLocaleByReference,
} from '@salesforce/retail-react-app/app/utils/site-utils';
import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
import { getEnvBasePath, slasPrivateProxyPath } from '@salesforce/pwa-kit-runtime/utils/ssr-namespace-paths';
import { createUrlTemplate } from '@salesforce/retail-react-app/app/utils/url';
import createLogger from '@salesforce/pwa-kit-runtime/utils/logger-factory';
import { getPasswordlessCallbackUrl } from '@salesforce/retail-react-app/app/utils/auth-utils';

import { CommerceApiProvider } from '@salesforce/commerce-sdk-react';
import { withReactQuery } from '@salesforce/pwa-kit-react-sdk/ssr/universal/components/with-react-query';
import { useCorrelationId } from '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks';
import { getAppOrigin } from '@salesforce/pwa-kit-react-sdk/utils/url';
import { generateSfdcUserAgent } from '@salesforce/retail-react-app/app/utils/sfdc-user-agent-utils';
import {
  DEFAULT_DNT_STATE,
  STORE_LOCATOR_RADIUS,
  STORE_LOCATOR_RADIUS_UNIT,
  STORE_LOCATOR_DEFAULT_COUNTRY,
  STORE_LOCATOR_DEFAULT_COUNTRY_CODE,
  STORE_LOCATOR_DEFAULT_POSTAL_CODE,
  STORE_LOCATOR_DEFAULT_PAGE_SIZE,
  STORE_LOCATOR_SUPPORTED_COUNTRIES,
} from '@salesforce/retail-react-app/app/constants';
import { ContentfulLivePreviewProvider } from '@contentful/live-preview/react';

// Loaded via React.lazy(), gated to development below, so the devtools chunk is registered but
// never fetched in production — @tanstack/react-query-devtools's own top-level `require` of its
// devtools implementation isn't NODE_ENV-gated, so a static import would still ship that code to
// every shopper even though the exported component renders null outside development (SFCC-860,
// flagged by Lighthouse's unused-javascript audit).
const ReactQueryDevtools = lazy(() =>
  import('@tanstack/react-query-devtools').then((module) => ({ default: module.ReactQueryDevtools })),
);

// Contentful's image CDN — used by every Contentful-driven page (home, experience) for hero/PLP
// imagery. Preconnecting here (rather than per-page) guarantees the hint is in the very first
// server-rendered <head>, which is when the browser can actually act on it (SFCC-860, Lighthouse's
// uses-rel-preconnect audit). No crossOrigin attribute — Contentful images are always rendered as
// plain <img src> with no crossOrigin prop, so the request is always same-mode (anonymous).
const CONTENTFUL_IMAGE_CDN_ORIGIN = 'https://images.ctfassets.net';

const sfdcUserAgent = generateSfdcUserAgent();

type SiteLocale = {
  id: string;
  alias?: string;
  preferredCurrency: string;
};

// sfccSiteId overrides the SFCC Commerce API siteId for PWA sites whose ID differs from the
// SFCC site ID (e.g. ZimmermannEUfr → SFCC ZimmermannEU).
type SiteConfig = {
  id: string;
  sfccSiteId?: string;
  alias?: string;
  l10n: {
    defaultLocale: string;
    supportedLocales: SiteLocale[];
  };
};

type AppLocals = {
  appConfig?: {
    commerceAPI: {
      proxyPath: string;
      parameters: {
        shortCode: string;
        clientId: string;
        organizationId: string;
        siteId?: string;
      };
    };
    login?: {
      passwordless?: {
        callbackURI?: string;
      };
    };
    einsteinAPI?: unknown;
  };
  site?: Pick<SiteConfig, 'id' | 'sfccSiteId' | 'alias'>;
  locale?: Pick<SiteLocale, 'id' | 'preferredCurrency'>;
  buildUrl?: ReturnType<typeof createUrlTemplate>;
  originalUrl?: string;
};

type AppConfigProps = {
  children: React.ReactNode;
  locals?: AppLocals;
};

/**
 * Use the AppConfig component to inject extra arguments into the getProps
 * methods for all Route Components in the app – typically you'd want to do this
 * to inject a connector instance that can be used in all Pages.
 *
 * You can also use the AppConfig to configure a state-management library such
 * as Redux, or Mobx, if you like.
 */
const AppConfig = ({ children, locals = {} }: AppConfigProps): React.ReactElement => {
  const { correlationId } = useCorrelationId();
  const headers = {
    'correlation-id': correlationId,
    sfdc_user_agent: sfdcUserAgent,
  };

  if (!locals.appConfig) throw new Error('AppConfig: locals.appConfig is required');
  const commerceApiConfig = locals.appConfig.commerceAPI;
  const locale = locals.locale?.id ?? 'en-US';

  const appOrigin = getAppOrigin();
  const passwordlessCallbackURI = getPasswordlessCallbackUrl(locals.appConfig?.login?.passwordless?.callbackURI);

  const storeLocatorConfig = {
    radius: STORE_LOCATOR_RADIUS,
    radiusUnit: STORE_LOCATOR_RADIUS_UNIT,
    defaultCountry: STORE_LOCATOR_DEFAULT_COUNTRY,
    defaultCountryCode: STORE_LOCATOR_DEFAULT_COUNTRY_CODE,
    defaultPostalCode: STORE_LOCATOR_DEFAULT_POSTAL_CODE,
    defaultPageSize: STORE_LOCATOR_DEFAULT_PAGE_SIZE,
    supportedCountries: STORE_LOCATOR_SUPPORTED_COUNTRIES,
  };

  // Set absolute uris for CommerceApiProvider proxies and callbacks
  const redirectURI = `${appOrigin}${getEnvBasePath()}/callback`;
  const proxy = `${appOrigin}${getEnvBasePath()}${commerceApiConfig.proxyPath}`;
  const slasPrivateClientProxyEndpoint = `${appOrigin}${getEnvBasePath()}${slasPrivateProxyPath}`;

  return (
    <>
      <Helmet>
        <link rel="preconnect" href={CONTENTFUL_IMAGE_CDN_ORIGIN} />
      </Helmet>
      <CommerceApiProvider
        shortCode={commerceApiConfig.parameters.shortCode}
        clientId={commerceApiConfig.parameters.clientId}
        organizationId={commerceApiConfig.parameters.organizationId}
        siteId={locals.site?.sfccSiteId ?? locals.site?.id ?? ''}
        locale={locale}
        currency={locals.locale?.preferredCurrency ?? ''}
        redirectURI={redirectURI}
        proxy={proxy}
        headers={headers}
        defaultDnt={DEFAULT_DNT_STATE}
        logger={createLogger({ packageName: 'commerce-sdk-react' })}
        passwordlessLoginCallbackURI={passwordlessCallbackURI}
        // Set 'enablePWAKitPrivateClient' to true to use SLAS private client login flows.
        // Make sure to also enable useSLASPrivateClient in ssr.js when enabling this setting.
        enablePWAKitPrivateClient={true}
        privateClientProxyEndpoint={slasPrivateClientProxyEndpoint}
        // Uncomment 'hybridAuthEnabled' if the current site has Hybrid Auth enabled. Do NOT set this flag for hybrid storefronts using Plugin SLAS.
        // hybridAuthEnabled={true}
      >
        <MultiSiteProvider site={locals.site} locale={locals.locale} buildUrl={locals.buildUrl}>
          <StoreLocatorProvider config={storeLocatorConfig}>
            <ContentfulLivePreviewProvider locale={locale} enableInspectorMode enableLiveUpdates>
              <ChakraProvider theme={theme}>
                <ZimmFontFace />
                <ZimmTokensGlobal />
                <UiCopyProvider>{children}</UiCopyProvider>
              </ChakraProvider>
            </ContentfulLivePreviewProvider>
          </StoreLocatorProvider>
        </MultiSiteProvider>
        {process.env.NODE_ENV === 'development' && (
          <Suspense fallback={null}>
            <ReactQueryDevtools />
          </Suspense>
        )}
      </CommerceApiProvider>
    </>
  );
};

AppConfig.restore = (locals: AppLocals = {}): void => {
  const path =
    typeof window === 'undefined' ? locals.originalUrl ?? '/' : `${window.location.pathname}${window.location.search}`;

  // resolveSiteFromUrl only matches a site alias/ID in the URL. When url.site is 'none' the site
  // segment is absent, so it always falls back to the defaultSite. In that case, find the real site
  // by matching the locale alias from the URL against each site's supportedLocales.
  const defaultResolved = resolveSiteFromUrl(path);
  const { localeRef } = getParamsFromPath(path);
  type SupportedLocale = { id: string; alias?: string };
  // sfccSiteId overrides the SFCC Commerce API siteId for PWA sites that don't share their ID
  // with their SFCC counterpart (e.g. ZimmermannEUfr → SFCC ZimmermannEU).
  type Site = {
    id: string;
    sfccSiteId?: string;
    alias?: string;
    l10n: { defaultLocale: string; supportedLocales: SupportedLocale[] };
  };
  const site: Site = localeRef
    ? (getSites() as Site[]).find((s) =>
        s.l10n.supportedLocales.some((l) => l.alias === localeRef || l.id === localeRef),
      ) ?? defaultResolved
    : defaultResolved;

  // resolveLocaleFromUrl also calls resolveSiteFromUrl internally, so it would return the wrong
  // site too. Resolve the locale directly from the site we already found above.
  const locale = (getLocaleByReference(site, localeRef ?? site.l10n.defaultLocale) ??
    getLocaleByReference(site, site.l10n.defaultLocale)) as SiteLocale;

  const { app: appConfig } = getConfig() as { app: NonNullable<AppLocals['appConfig']> };
  const apiConfig = {
    ...appConfig.commerceAPI,
    einsteinConfig: appConfig.einsteinAPI,
  };

  apiConfig.parameters.siteId = site.sfccSiteId ?? site.id;

  locals.buildUrl = createUrlTemplate(appConfig, site.alias || site.id, locale.alias || locale.id);
  locals.site = site;
  locals.locale = locale;
  locals.appConfig = appConfig;
};

AppConfig.freeze = (): undefined => undefined;

AppConfig.extraGetPropsArgs = (locals: AppLocals = {}): Record<string, unknown> => {
  return {
    buildUrl: locals.buildUrl,
    site: locals.site,
    locale: locals.locale,
  };
};

const isServerSide = typeof window === 'undefined';

// Recommended settings for PWA-Kit usages.
// NOTE: they will be applied on both server and client side.
// retry is always disabled on server side regardless of the value from the options
const options = {
  queryClientConfig: {
    defaultOptions: {
      queries: {
        retry: false,
        refetchOnWindowFocus: false,
        staleTime: 10 * 1000,
        ...(isServerSide ? { retryOnMount: false } : {}),
      },
      mutations: {
        retry: false,
      },
    },
  },
};

export default withReactQuery(AppConfig, options);

