import React, { useEffect } from 'react';
import { useIntl } from 'react-intl';
import { useLocation } from 'react-router-dom';

// Components
import { Box, Stack, Link, Text, Spinner } from '@salesforce/retail-react-app/app/components/shared/ui';

// Project Components
import Seo from '@salesforce/retail-react-app/app/components/seo';
import Section from '@salesforce/retail-react-app/app/components/section';
import ProductScroller from '@salesforce/retail-react-app/app/components/product-scroller';

// Hooks
import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
import { useContentfulEntries, useContentfulEntry } from '../../hooks/useContentful';
import { useContentfulLiveUpdates } from '@contentful/live-preview/react';

// Constants
import {
  HOME_SHOP_PRODUCTS_CATEGORY_ID,
  HOME_SHOP_PRODUCTS_LIMIT,
  MAX_CACHE_AGE,
  STALE_WHILE_REVALIDATE,
} from '../../constants';

import { useServerContext } from '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks';
import { useProductSearch } from '@salesforce/commerce-sdk-react';

// Types
import type { HomepageEntry, AnyContentfulEntry } from '../../types/contentful';

// --- Shared layout ---

const HomepageContent = () => {
  const intl = useIntl();

  const { data: productSearchResult, isLoading: productsLoading } = useProductSearch({
    parameters: {
      refine: [`cgid=${HOME_SHOP_PRODUCTS_CATEGORY_ID as string}`, 'htype=master'] as unknown as string, // SDK types refine as string but runtime accepts string[]
      expand: ['promotions', 'variations', 'prices', 'images', 'custom_properties'],
      perPricebook: true,
      allVariationProperties: true,
      limit: HOME_SHOP_PRODUCTS_LIMIT,
    },
  });

  return (
    <>
      {productSearchResult && (
        // From PWA template - Example on how to show products
        <Section
          padding={4}
          paddingTop={16}
          title={intl.formatMessage({
            defaultMessage: 'Shop Products',
            id: 'home.heading.shop_products',
          })}
          subtitle={intl.formatMessage(
            {
              defaultMessage: 'This section contains content from the catalog. {docLink} on how to replace it.',
              id: 'home.description.shop_products',
              description:
                '{docLink} is a html button that links the user to https://sfdc.co/business-manager-manage-catalogs',
            },
            {
              docLink: (
                <Link
                  target="_blank"
                  href={'https://sfdc.co/business-manager-manage-catalogs'}
                  textDecoration={'none'}
                  position={'relative'}
                  _after={{
                    position: 'absolute',
                    content: `""`,
                    height: '2px',
                    bottom: '-2px',
                    margin: '0 auto',
                    left: 0,
                    right: 0,
                    background: 'gray.700',
                  }}
                  _hover={{ textDecoration: 'none' }}
                >
                  {intl.formatMessage({
                    defaultMessage: 'Read docs',
                    id: 'home.link.read_docs',
                  })}
                </Link>
              ),
            },
          )}
        >
          <Stack pt={8} spacing={16}>
            <ProductScroller products={productSearchResult?.hits} isLoading={productsLoading} />
          </Stack>
        </Section>
      )}
    </>
  );
};

// --- Normal (published) home ---

const HomeNormal = () => {
  const einstein = useEinstein();
  const { pathname } = useLocation();

  const { res } = useServerContext();
  if (res) {
    res.set(
      'Cache-Control',
      `s-maxage=${MAX_CACHE_AGE as number}, stale-while-revalidate=${STALE_WHILE_REVALIDATE as number}`,
    );
  }

  const { data: contentfulData, isLoading: contentfulLoading } = useContentfulEntries<HomepageEntry>('homepage');
  const homepageContent = useContentfulLiveUpdates(contentfulData?.[0] ?? null);

  useEffect(() => {
    einstein.sendViewPage(pathname);
  }, []);

  if (contentfulLoading) {
    return (
      <Box display="flex" justifyContent="center" py={16}>
        <Spinner size="xl" />
      </Box>
    );
  }

  if (!homepageContent) return null;

  return <HomepageContent />;
};

// --- Preview (draft) home ---

type HomePreviewContentProps = {
  entryId: string;
};

const HomePreviewContent = ({ entryId }: HomePreviewContentProps) => {
  const { data, isLoading, error } = useContentfulEntry<AnyContentfulEntry>(entryId, true);
  const liveData = useContentfulLiveUpdates(data);

  if (isLoading) {
    return (
      <Box display="flex" justifyContent="center" py={16}>
        <Spinner size="xl" />
      </Box>
    );
  }

  if (error) {
    return (
      <Box p={8}>
        <Text color="red.500">Error loading preview: {error.message}</Text>
      </Box>
    );
  }

  if (!liveData) return null;

  const contentTypeId = liveData.sys?.contentType?.sys?.id;

  if (contentTypeId !== 'homepage') {
    return (
      <Box p={8}>
        <Text>Preview for content type &ldquo;{contentTypeId}&rdquo; is not yet configured.</Text>
      </Box>
    );
  }

  return <HomepageContent />;
};

// --- Page ---

const Home = () => {
  const { search } = useLocation();
  const entryId = new URLSearchParams(search).get('entry');

  return (
    <Box data-testid="home-page">
      <Seo
        title="Home Page"
        description="Commerce Cloud Retail React App"
        keywords="Commerce Cloud, Retail React App, React Storefront"
      />
      {entryId ? <HomePreviewContent entryId={entryId} /> : <HomeNormal />}
    </Box>
  );
};

Home.getTemplateName = () => 'home';

export default Home;

